#include <algorithm>
#include <iostream>
#include <utility>
#include <vector>
using namespace std;
int main(){ ios::sync_with_stdio(false); cin.tie(nullptr); int n; if(!(cin>>n)) return 0; vector<pair<long long,long long>> p(n); for(int i=0;i<n;i++) cin>>p[i].first>>p[i].second; sort(p.begin(),p.end()); vector<int> dp(n,1); int ans=1; for(int i=0;i<n;i++){ for(int j=0;j<i;j++){ if(p[j].first<=p[i].first && p[j].second<=p[i].second) dp[i]=max(dp[i],dp[j]+1); } ans=max(ans,dp[i]); } cout<<ans<<'\n'; return 0; }
